def _numpy_to_list(embeddings: np.ndarray) -> List[List[float]]:
    """Convert numpy array to list for JSON serialization."""
    if embeddings.ndim == 1:
        return embeddings.tolist()
    elif embeddings.ndim == 2:
        return embeddings.tolist()
    else:
        raise ValueError(f"Unsupported embedding dimensions: {embeddings.ndim}")


